/**
 * Reference output of inkvec 0.2.7 for the scenes of `region-scenes.ts`: its palette, its
 * labels, and every label map after despeckle, sliver absorption, pixel reassignment, the
 * second despeckle and the face split (`regions.rs`), the regularization (`regularize.rs`)
 * and, for the scene with transparency, the native palette and the four-channel blend passes
 * (`native.rs`). Each pass is fed inkvec's own input to it. Label maps are run-length
 * encoded: `label*count`, comma-separated.
 */

/** One run of the classic clean-up, every stage's output. */
export interface ParityCase {
  name: string
  min: number
  sigma: number
  labels0: string
  despeckle: string
  absorbed: number
  absorb: string
  moved: number
  reassign: string
  despeckle2: string
  faces: string
  faceLabel: number[]
}

/** One run of the four-channel blend passes. */
export interface NativeParityCase {
  name: string
  min: number
  sigma: number
  labels0: string
  despeckle: string
  absorbed: number
  absorb: string
  moved: number
  reassign: string
}

export interface ParityFixture {
  name: string
  sigma: number
  pal: number[]
  cases: ParityCase[]
  regularize: {
    residualSigma: number
    incoherence: number
    residualSigmaSpeckled: number
    incoherenceSpeckled: number
    sigmaLossy: number
    changes: number
    labels: string
    changesSpeckled: number
    labelsSpeckled: string
  }
  native: { pal: number[]; palAlpha: number[]; cases: NativeParityCase[] } | null
}

